; selfmod.asm -- chapter 8: a program that changes its own number
; generated by gen08.py
        INCLUDE "msx.inc"
        OUTPUT "selfmod.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
RESULTS EQU RAM_START          ; what the program found: the debugger reads it here
; The number in LD A,n is the byte after the opcode, and the program writes
; to it. Run in the cartridge, the write changes nothing; the same four lines
; copied into the RAM change themselves. WHERE IT BREAKS.
init:   di
        ld sp, SYS_AREA
        call inrom              ; the routine where the cartridge has it
        ld (RESULTS), a         ; what LD A,n loaded
        ld hl, copy             ; the same routine, copied into the RAM ...
        ld de, inram
        ld bc, copy_end - copy
        ldir                    ; (LDIR copies BC bytes: chapter 13)
        call inram              ; ... and run there
        ld (RESULTS + 1), a
stop:   jr stop

inrom:  ld a, $47
        ld (rpatch + 1), a      ; the byte after the opcode, in the ROM
rpatch: ld a, $00               ; assembled as LD A,0
        ret

copy:                           ; the same lines, assembled to run at $C010
        DISP RAM_START + $10
inram:  ld a, $47
        ld (mpatch + 1), a      ; the byte after the opcode, in the RAM
mpatch: ld a, $00               ; assembled as LD A,0
        ret
        ENT
copy_end:
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
